  assign _t10 = (_t8 ? {((req_line == 2'h3) ? 1'h1 : dirty[3:3]), ((req_line == 2'h2) ? 1'h1 : dirty[2:2]), ((req_line == 2'h1) ? 1'h1 : dirty[1:1]), ((req_line == 2'h0) ? 1'h1 : dirty[0:0])} : dirty);
  assign _t11 = ((req_valid & (req_op == 2'h2)) & (({62'h0, req_line} < 64'h4) ? (req_line[1:1] ? (req_line[0:0] ? _t9[3:3] : _t9[2:2]) : (req_line[0:0] ? _t9[1:1] : _t9[0:0])) : _t9[0:0]));
  assign _t12 = (_t11 ? {((req_line == 2'h3) ? 1'h0 : _t9[3:3]), ((req_line == 2'h2) ? 1'h0 : _t9[2:2]), ((req_line == 2'h1) ? 1'h0 : _t9[1:1]), ((req_line == 2'h0) ? 1'h0 : _t9[0:0])} : _t9);
