module mkLineState_rules (
  input wire clock,
  input wire reset,
  input wire req_valid,
  input wire [1:0] req_op,
  input wire [1:0] req_line,
  output wire io_hit,
  output wire io_writeback,
  output wire [3:0] io_valid,
  output wire [3:0] io_dirty
);
  mkLineState_rules_core core (
    .clk(clock),
    .rst(1'h0),
    .reset(reset),
    .req_valid(req_valid),
    .req_op(req_op),
    .req_line(req_line),
    .io_hit(io_hit),
    .io_writeback(io_writeback),
    .io_valid(io_valid),
    .io_dirty(io_dirty)
  );
endmodule

