    misses <= misses + 1;
  endrule

  rule write (isWr);
    valid[req_line] <= True;
    dirty[req_line] <= True;
  endrule

  rule evict (isEv && hit);
    valid[req_line] <= False;
    dirty[req_line] <= False;
  endrule

  rule countWb (isEv && hit && dirty[req_line]);
    writebacks <= writebacks + 1;
